"""## K-FOLD"""

import os
import numpy as np
import tensorflow as tf
from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import classification_report, confusion_matrix, accuracy_score, roc_curve, auc
from sklearn.preprocessing import label_binarize
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Set output directory for saving plots
output_dir = "/content/drive/MyDrive/JackFruit/Raw_data_output_K_FOLD"
os.makedirs(output_dir, exist_ok=True)

# Define StratifiedKFold parameters
k = 5  # Number of folds
kf = StratifiedKFold(n_splits=k, shuffle=True, random_state=1)

# Define data generators for each fold
def create_fold_gen(train_idx, val_idx, image_df):
    train_data = image_df.iloc[train_idx]
    val_data = image_df.iloc[val_idx]

    data_gen = tf.keras.preprocessing.image.ImageDataGenerator(
        preprocessing_function=tf.keras.applications.mobilenet_v2.preprocess_input
    )

    train_images = data_gen.flow_from_dataframe(
        dataframe=train_data,
        x_col='Filepath',
        y_col='Label',
        target_size=(224, 224),
        color_mode='rgb',
        class_mode='categorical',
        batch_size=32,
        shuffle=True,
    )

    val_images = data_gen.flow_from_dataframe(
        dataframe=val_data,
        x_col='Filepath',
        y_col='Label',
        target_size=(224, 224),
        color_mode='rgb',
        class_mode='categorical',
        batch_size=32,
        shuffle=True,
    )

    return train_images, val_images

# Define model function
def get_model(model):
    kwargs = {
        'input_shape': (224, 224, 3),
        'include_top': False,
        'weights': 'imagenet',
        'pooling': 'avg'
    }
    pretrained_model = model(**kwargs)
    pretrained_model.trainable = False
    inputs = pretrained_model.input
    x = pretrained_model(inputs)
    x = tf.keras.layers.Dense(512, activation='sigmoid')(x)

    outputs = tf.keras.layers.Dense(6, activation='softmax')(x)

    model = tf.keras.Model(inputs=inputs, outputs=outputs)
    model.compile(
        optimizer=tf.keras.optimizers.Adam(learning_rate=0.0001),
        loss='categorical_crossentropy',
        metrics=['accuracy']
    )
    return model

# Define models and metrics storage
models = {
    "ResNet50V2": {"model": tf.keras.applications.ResNet50V2, "history": []},
    "DenseNet201": {"model": tf.keras.applications.DenseNet201, "history": []},
    "VGG19": {"model": tf.keras.applications.VGG19, "history": []},
}

# Prepare the labels for stratification
labels = image_df['Label'].factorize()[0]

# Perform k-Fold cross-validation
for name, model_info in models.items():
    val_accuracies, test_accuracies, misclass_errors = [], [], []
    all_y_trues, all_y_preds = [], []  # To collect final confusion matrix data across all folds
    model_output_dir = os.path.join(output_dir, name)
    os.makedirs(model_output_dir, exist_ok=True)

    fold = 1
    for train_idx, val_idx in kf.split(image_df, labels):
        print(f"Training fold {fold} for {name}...")

        # Create fold-specific training and validation generators
        train_images, val_images = create_fold_gen(train_idx, val_idx, image_df)

        # Initialize and compile model
        m = get_model(model_info["model"])
        m.compile(optimizer="adam", loss="categorical_crossentropy", metrics=["accuracy"])

        # Training the model
        history = m.fit(train_images, validation_data=val_images, epochs=20, verbose=1)
        models[name]["history"].append(history)

        # Evaluate on validation data
        val_loss, val_acc = m.evaluate(val_images, verbose=0)
        val_accuracies.append(val_acc)

        # Predict on validation data for confusion matrix and classification report
        y_pred_prob = m.predict(val_images)
        y_pred = np.argmax(y_pred_prob, axis=1)
        y_true = val_images.classes
        class_labels = list(val_images.class_indices.keys())

        # Append to lists for final confusion matrix calculation
        all_y_trues.append(y_true)
        all_y_preds.append(y_pred)

        # Confusion matrix
        cm = confusion_matrix(y_true, y_pred)
        plt.figure(figsize=(10, 6))
        sns.heatmap(cm, annot=True, fmt="d", cmap="Blues", xticklabels=class_labels, yticklabels=class_labels)
        plt.title(f"{name} Fold {fold} Confusion Matrix")
        plt.xlabel("Predicted")
        plt.ylabel("True")
        cm_plot = os.path.join(model_output_dir, f"{name}_fold{fold}_confusion_matrix.png")
        plt.savefig(cm_plot)
        plt.show()

        # Classification report
        print(f"\nClassification Report for {name} Fold {fold}:\n", classification_report(y_true, y_pred, target_names=class_labels))

        # ROC Curve and AUC for each class
        y_true_bin = label_binarize(y_true, classes=range(len(class_labels)))
        fpr, tpr, roc_auc = dict(), dict(), dict()
        plt.figure(figsize=(10, 8))

        for i in range(len(class_labels)):
            fpr[i], tpr[i], _ = roc_curve(y_true_bin[:, i], y_pred_prob[:, i])
            roc_auc[i] = auc(fpr[i], tpr[i])
            plt.plot(fpr[i], tpr[i], lw=2, label=f'Class {class_labels[i]} (AUC = {roc_auc[i]:.2f})')

        plt.plot([0, 1], [0, 1], "k--", lw=2)
        plt.xlabel("False Positive Rate")
        plt.ylabel("True Positive Rate")
        plt.title(f"{name} Fold {fold} ROC Curve")
        plt.legend(loc="lower right")
        roc_plot = os.path.join(model_output_dir, f"{name}_fold{fold}_ROC_Curve.png")
        plt.savefig(roc_plot)
        plt.show()

        # Misclassification error
        misclassification_error = 1 - accuracy_score(y_true, y_pred)
        misclass_errors.append(misclassification_error)
        print(f"{name} Fold {fold} Misclassification Error: {misclassification_error:.4f}")

        fold += 1

    # Store overall performance metrics
    models[name]['avg_val_accuracy'] = np.mean(val_accuracies)
    models[name]['avg_misclassification_error'] = np.mean(misclass_errors)
    print(f"\nAverage Validation Accuracy for {name}: {models[name]['avg_val_accuracy']:.4f}")
    print(f"Average Misclassification Error for {name}: {models[name]['avg_misclassification_error']:.4f}")

    # Final Confusion Matrix Aggregated Across All Folds
    final_y_true = np.concatenate(all_y_trues)
    final_y_pred = np.concatenate(all_y_preds)

    # Final Confusion Matrix Plot
    cm_matrix = confusion_matrix(final_y_true, final_y_pred)
    plt.figure(figsize=(10, 6), dpi=300)
    sns.heatmap(cm_matrix, annot=True, fmt='g', cmap='Blues',
                xticklabels=sorted(set(final_y_true)), yticklabels=sorted(set(final_y_true)))
    plt.title(f'{name} Final Confusion Matrix Across All Folds')
    plt.xlabel('Predicted')
    plt.ylabel('True')

    confusion_matrix_plot = os.path.join(model_output_dir, f"{name}_Final_Confusion_Matrix.png")
    plt.savefig(confusion_matrix_plot, bbox_inches='tight')
    plt.show()

