import os

# Define the base directory where your folders are located
base_dir = '/content/drive/MyDrive/JackFruit/DataSet/AugmentedJackfruit'

# Loop through each folder
for folder_name in ['Fruit damage', 'leaf blight', 'Rhizopus rot', 'Healthy leaf', 'Healthy jackfruit', 'Leaf spot']:
    folder_path = os.path.join(base_dir, folder_name)

    # Check if the folder exists
    if os.path.isdir(folder_path):
        # Get a list of all files in the folder
        file_list = os.listdir(folder_path)

        # Filter the list to include only image files (e.g., .jpg, .png, .bmp)
        image_list = [f for f in file_list if f.endswith(('.jpg', '.png', '.bmp','.JPG','.JPEG','.jpeg'))]

        # Print the folder name and the number of images
        print(f'{folder_name}: {len(image_list)} images')
    else:
        print(f'{folder_name} does not exist.')

