"""## Pretrained Model"""

# Model Training and Evaluation Script
def get_model(model):
    kwargs = {
        'input_shape': (224, 224, 3),
        'include_top': False,
        'weights': 'imagenet',
        'pooling': 'avg'
    }
    pretrained_model = model(**kwargs)
    pretrained_model.trainable = False
    inputs = pretrained_model.input
    x = pretrained_model(inputs)
    x = tf.keras.layers.Dense(512, activation='sigmoid')(x)

    outputs = tf.keras.layers.Dense(6, activation='softmax')(x)

    model = tf.keras.Model(inputs=inputs, outputs=outputs)
    model.compile(
        optimizer=tf.keras.optimizers.Adam(learning_rate=0.00001),
        loss='categorical_crossentropy',
        metrics=['accuracy']
    )
    return model
# Setting up the output directory for saving plots
output_dir = "/content/drive/MyDrive/JackFruit/AugmentedData"
os.makedirs(output_dir, exist_ok=True)

# Dictionary with the models
models = {
    "ResNet50V2": {"model": tf.keras.applications.ResNet50V2, "perf": 0},
    "DenseNet201": {"model": tf.keras.applications.DenseNet201, "perf": 0},
    "VGG19": {"model": tf.keras.applications.VGG19, "perf": 0},
}

# Training the models and recording performance
for name, model in models.items():
    # Create a subdirectory for each model
    model_output_dir = os.path.join(output_dir, name)
    os.makedirs(model_output_dir, exist_ok=True)

    m = get_model(model['model'])
    models[name]['model'] = m

    start = perf_counter()

    history = m.fit(train_images, validation_data=val_images, epochs=20, verbose=1)

    duration = perf_counter() - start
    duration = round(duration, 2)
    models[name]['perf'] = duration

    val_acc = history.history['val_accuracy']
    models[name]['val_acc'] = [round(v, 4) for v in val_acc]

    train_acc = history.history['accuracy']
    models[name]['train_accuracy'] = [round(v, 4) for v in train_acc]

    results = m.evaluate(test_images, verbose=0)
    res = results[1]
    models[name]['test_accuracy'] = [round(res, 4)]

    # Plotting training accuracy
    plt.figure()
    pd.DataFrame(history.history)[['accuracy', 'val_accuracy']].plot()
    plt.title(f"{name} Training Accuracy")
    plt.xticks(range(0, 20, 2))
    accuracy_plot = os.path.join(model_output_dir, f"{name}_accuracy_plot.png")
    plt.savefig(accuracy_plot)
    plt.show()

    # Plotting training loss
    plt.figure()
    pd.DataFrame(history.history)[['loss', 'val_loss']].plot()
    plt.title(f"{name} Training Loss")
    plt.xticks(range(0, 20, 2))
    loss_plot = os.path.join(model_output_dir, f"{name}_loss_plot.png")
    plt.savefig(loss_plot)
    plt.show()
    # print(f"\nAccuracy on the test set for {name}: {results[1] * 100:.2f}%")
    pred = m.predict(test_images)
    pred = np.argmax(pred, axis=1)

    labels = train_images.class_indices
    labels = dict((v, k) for k, v in labels.items())
    pred = [labels[k] for k in pred]
    y_test = list(test_df.Label)
    # print('Accuracy:', np.round(metrics.accuracy_score(y_test, pred), 5))
    # print('Precision:', np.round(metrics.precision_score(y_test, pred, average='weighted'), 5))
    # print('Recall:', np.round(metrics.recall_score(y_test, pred, average='weighted'), 5))
    # print('F1 Score:', np.round(metrics.f1_score(y_test, pred, average='weighted'), 5))
    # print(classification_report(y_test, pred))
    # Confusion Matrix
    print(f"{name} Confusion Matrix: \n\n")
    cf_matrix = sklearn_confusion_matrix(y_test, pred, normalize='true')
    plt.figure(figsize=(10, 6))
    sns.heatmap(cf_matrix, annot=True, cmap='Blues',
                xticklabels=sorted(set(y_test)), yticklabels=sorted(set(y_test)))
    plt.title(f'{name} Normalized Confusion Matrix')
    confusion_matrix_plot = os.path.join(model_output_dir, f"{name}_confusion_matrix.png")
    plt.savefig(confusion_matrix_plot)
    plt.show()

    # FP = cf_matrix.sum(axis=0) - np.diag(cf_matrix)
    # FN = cf_matrix.sum(axis=1) - np.diag(cf_matrix)
    # TP = np.diag(cf_matrix)
    # TN = len(y_test) - (FP + FN + TP)

    # TPR = TP / (TP + FN)
    # TNR = TN / (TN + FP)
    # PPV = TP / (TP + FP)
    # NPV = TN / (TN + FN)
    # FPR = FP / (FP + TN)
    # FNR = FN / (TP + FN)
    # FDR = FP / (TP + FP)

    # print(f"{name} Recall (Sensitivity):", np.mean(TPR) * 100)
    # print(f"{name} Specificity:", np.mean(TNR) * 100)
    # print(f"{name} Precision:", np.mean(PPV) * 100)
    # print(f"{name} False Positive Rate:", np.mean(FPR) * 100)
    # print(f"{name} False Negative Rate:", np.mean(FNR) * 100)
    # print(f"{name} Negative Predictive Value:", np.mean(NPV) * 100)
    # print(f"{name} False Discovery Rate:", np.mean(FDR) * 100)

    # ROC Curve Calculation and Plotting with distinct colors for each class
    print(f"\n{ '=' * 20 } { name } {'=' * 20 }")
    unique_classes = np.unique(y_test)
    y_test_bin = label_binarize(y_test, classes=unique_classes)
    y_score = m.predict(test_images)

    fpr, tpr, roc_auc = {}, {}, {}
    for i in range(6):
        fpr[i], tpr[i], _ = roc_curve(y_test_bin[:, i], y_score[:, i])
        roc_auc[i] = auc(fpr[i], tpr[i])

    fpr["micro"], tpr["micro"], _ = roc_curve(y_test_bin.ravel(), y_score.ravel())
    roc_auc["micro"] = auc(fpr["micro"], tpr["micro"])

    plt.figure(figsize=(10, 6))
    colors = ['blue', 'green', 'red', 'orange', 'purple', 'brown']  # Unique colors for each class
    for i, color in zip(range(6), colors):
        plt.plot(fpr[i], tpr[i], color=color, lw=2, label=f'Class {i} (AUC = {roc_auc[i]:.2f})')

    plt.plot(fpr["micro"], tpr["micro"], color='black', label=f'Micro-average (AUC = {roc_auc["micro"]:.2f})', linestyle=':', linewidth=4)

    plt.plot([0, 1], [0, 1], 'k--', linewidth=2)
    plt.xlabel('False Positive Rate')
    plt.ylabel('True Positive Rate')
    plt.title(f'{name} ROC Curve for each Class')
    plt.legend(loc='lower right')

    roc_plot = os.path.join(model_output_dir, f"{name}_ROC_Curve.png")
    plt.savefig(roc_plot)
    plt.show()

    test_images.reset()
    y_pred = m.predict(test_images)
    y_pred_classes = np.argmax(y_pred, axis=1)
    y_true = test_images.classes
    misclassification_error = 1 - accuracy_score(y_true, y_pred_classes)

    print(f'{name} Misclassification Error: {misclassification_error:.4f}')

    # Final Confusion Matrix Plot
    cm_matrix = sklearn_confusion_matrix(y_true, y_pred_classes)
    plt.figure(figsize=(10, 6), dpi=300)
    sns.heatmap(cm_matrix, annot=True, fmt='g', cmap='Blues',
                xticklabels=sorted(set(y_true)), yticklabels=sorted(set(y_true)))
    plt.title(f'{name} Confusion Matrix')
    plt.xlabel('Predicted')
    plt.ylabel('True')

    confusion_matrix_plot = os.path.join(model_output_dir, f"{name}_Confusion_Matrix.png")
    plt.savefig(confusion_matrix_plot, bbox_inches='tight')
    plt.show()

"""# Ablation Study Hybrid Model

## Data Split
"""

def create_gen():
    # Load the Images with a generator and Data Augmentation
    train_generator = tf.keras.preprocessing.image.ImageDataGenerator(
        preprocessing_function=tf.keras.applications.mobilenet_v2.preprocess_input,
        validation_split=0.1
    )

    test_generator = tf.keras.preprocessing.image.ImageDataGenerator(
        preprocessing_function=tf.keras.applications.mobilenet_v2.preprocess_input
    )

    train_images = train_generator.flow_from_dataframe(
        dataframe=train_df,
        x_col='Filepath',
        y_col='Label',
        target_size=(224, 224),
        color_mode='rgb',
        class_mode='categorical',
        batch_size=16,
        shuffle=True,
    )

    val_images = train_generator.flow_from_dataframe(
        dataframe=train_df,
        x_col='Filepath',
        y_col='Label',
        target_size=(224, 224),
        color_mode='rgb',
        class_mode='categorical',
        batch_size=16,
        shuffle=True,
    )

    test_images = test_generator.flow_from_dataframe(
        dataframe=test_df,
        x_col='Filepath',
        y_col='Label',
        target_size=(224, 224),
        color_mode='rgb',
        class_mode='categorical',
        batch_size=16,
        shuffle=False
    )

    return train_generator,test_generator,train_images,val_images,test_images
# Separate in train and test data
train_df, test_df = train_test_split(image_df, train_size=0.8, shuffle=True, random_state=1)
# Create the generators
train_generator,test_generator,train_images,val_images,test_images=create_gen()

"""## LR .0001"""

import tensorflow as tf
from tensorflow.keras.layers import Input, Dense, GlobalAveragePooling2D, Concatenate, BatchNormalization, Activation, Dropout
from tensorflow.keras.models import Model
from tensorflow.keras.applications import DenseNet201, VGG19
from tensorflow.keras.optimizers import Adam
from tensorflow.keras.regularizers import l2
from tensorflow.keras.callbacks import EarlyStopping
# Define the input shape
input_shape = (224, 224, 3)

# Enable mixed precision
policy = tf.keras.mixed_precision.Policy('mixed_float16')
tf.keras.mixed_precision.set_global_policy(policy)

# Define the input layer
input_layer = Input(shape=input_shape, name='input_layer')

# Load pre-trained models
densenet_model = DenseNet201(weights='imagenet', include_top=False, input_tensor=input_layer)
vgg19_model = VGG19(weights='imagenet', include_top=False, input_tensor=input_layer)

# Global average pooling layer for each model
densenet_gap = GlobalAveragePooling2D()(densenet_model.output)
vgg19_gap = GlobalAveragePooling2D()(vgg19_model.output)

# Concatenate the outputs from both models
concatenated_features = Concatenate()([densenet_gap, vgg19_gap])

# Adding Batch Normalization before the Dense layer
concatenated_features_bn = BatchNormalization()(concatenated_features)

# Additional dense layers for further processing with L2 regularization and Dropout
dense_layer1 = Dense(1024, kernel_regularizer=l2(0.001))(concatenated_features_bn)  # Increasing the number of units
dense_layer1_bn = BatchNormalization()(dense_layer1)
dense_layer1_act = Activation('relu')(dense_layer1_bn)
dense_layer1_dropout = Dropout(0.5)(dense_layer1_act)

dense_layer2 = Dense(512, kernel_regularizer=l2(0.001))(dense_layer1_dropout)  # Increasing the number of units
dense_layer2_bn = BatchNormalization()(dense_layer2)
dense_layer2_act = Activation('relu')(dense_layer2_bn)
dense_layer2_dropout = Dropout(0.5)(dense_layer2_act)

# Output layer for 6-class classification
output_layer = Dense(6, activation='softmax', dtype='float32')(dense_layer2_dropout)  # Changing the output layer to 6 units

# Create the hybrid model
hybrid_model = Model(inputs=input_layer, outputs=output_layer)
early_stopping = EarlyStopping(
    monitor='val_loss',  # Monitors validation loss
    patience=3,
    restore_best_weights=True,
    verbose=1
)
# Compile the model using the Adam optimizer with a tunable learning rate
optimizer = Adam(learning_rate=0.0001,clipnorm=1.0)  # Consider tuning the learning rate
hybrid_model.compile(optimizer=optimizer, loss='categorical_crossentropy', metrics=['accuracy'])

# Fit the model
history = hybrid_model.fit(train_images, validation_data=val_images, epochs=20, verbose=1, callbacks=[early_stopping])


# Directory to save the figures
output_dir = '/content/drive/MyDrive/JackFruit/AblationStudy/LR/r.0001'
os.makedirs(output_dir, exist_ok=True)
print('\n')

val_acc = history.history['val_accuracy']
train_acc = history.history['accuracy']
results = hybrid_model.evaluate(test_images, verbose=0)
res = results[1]
test_acc = [round(res, 4)]

# Plotting training accuracy and loss
plt.figure()
pd.DataFrame(history.history)[['accuracy', 'val_accuracy']].plot()
plt.title("Training Accuracy")
plt.xticks(range(0, 20, 2))
plt.savefig(os.path.join(output_dir, 'training_accuracy_plot.png'))
plt.show()

plt.figure()
pd.DataFrame(history.history)[['loss', 'val_loss']].plot()
plt.title("Training Loss")
plt.xticks(range(0, 20, 2))
plt.savefig(os.path.join(output_dir, 'training_loss_plot.png'))
plt.show()

# Evaluate model performance
pred = hybrid_model.predict(test_images)
pred = np.argmax(pred, axis=1)

# Map the label
labels = (train_images.class_indices)
labels = dict((v, k) for k, v in labels.items())
pred = [labels[k] for k in pred]
y_test = list(test_df.Label)

# Apply a consistent and appealing style
sns.set(style="whitegrid")

print(f"\n{'=' * 20} Model: Hybrid Model {'=' * 20}")

test_images.reset()

# Predictions
y_pred = hybrid_model.predict(test_images)
y_pred_classes = np.argmax(y_pred, axis=1)

# True labels
y_true = test_images.classes

# Misclassification error
misclassification_error = 1 - accuracy_score(y_true, y_pred_classes)
print(f'Misclassification Error: {misclassification_error:.4f}')

class_labels = ['Fruit Damage', 'leaf blight', 'Rhizopus rot', 'Healthy leaf', 'Healthy jackfruit', 'Leaf spot']

# Confusion matrix
cm = confusion_matrix(y_true, y_pred_classes)
plt.figure(figsize=(10, 8), dpi=300)
sns.heatmap(cm, annot=True, fmt='g', cmap='Blues', xticklabels=class_labels, yticklabels=class_labels)
plt.title('Confusion Matrix')
plt.xlabel('Predicted')
plt.ylabel('True')

# Save the confusion matrix plot
cm_plot_path = os.path.join(output_dir, 'confusion_matrix_hybrid.png')
plt.savefig(cm_plot_path, bbox_inches='tight')
plt.show()

