concatenated_features_bn = BatchNormalization()(concatenated_features)


# Additional dense layers for further processing with L2 regularization and Dropout
dense_layer1 = Dense(1024, kernel_regularizer=l2(0.0005))(concatenated_features_bn)  # Increasing the number of units
dense_layer1_bn = BatchNormalization()(dense_layer1)
dense_layer1_act = LeakyReLU(alpha=0.1)(dense_layer1_bn)  # Using LeakyReLU with alpha of 0.1
dense_layer1_dropout = Dropout(0.3)(dense_layer1_act)

dense_layer2 = Dense(512, kernel_regularizer=l2(0.0005))(dense_layer1_dropout)  # Increasing the number of units
dense_layer2_bn = BatchNormalization()(dense_layer2)
dense_layer2_act = LeakyReLU(alpha=0.1)(dense_layer2_bn)  # Using LeakyReLU with alpha of 0.1
