from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Conv2D, MaxPooling2D, Flatten, Dense, Dropout, BatchNormalization
from tensorflow.keras.optimizers import Adam
import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from tensorflow.keras.models import load_model
from sklearn import metrics
from sklearn.metrics import classification_report, confusion_matrix
from statistics import mean
def custom_cnn_model():
    model = Sequential()

    # First Convolutional Block
    model.add(Conv2D(32, (3, 3), activation='relu', kernel_initializer='he_uniform', padding='same', input_shape=(224, 224, 3)))
    model.add(BatchNormalization())
    model.add(MaxPooling2D((2, 2)))

    # Fully Connected Block
    model.add(Flatten())
    model.add(Dense(256, activation='relu', kernel_initializer='he_uniform'))
    model.add(BatchNormalization())
    model.add(Dropout(0.5))
    model.add(Dense(128, activation='relu', kernel_initializer='he_uniform'))
    model.add(BatchNormalization())
    model.add(Dropout(0.3))

    # Output Layer
    model.add(Dense(6, activation='softmax'))

    # Compile the Model
    opt = Adam(learning_rate=0.001)
    model.compile(optimizer=opt, loss='categorical_crossentropy', metrics=['accuracy'])

    return model
# Fit the model
custom_cnn = custom_cnn_model()
history_cnn = custom_cnn.fit(train_images, validation_data=val_images,batch_size=32, epochs=20, verbose=1)
# Directory to save the figures
output_dir = '/content/drive/MyDrive/JackFruit/Ablation/CustomCNNModel/s1'
os.makedirs(output_dir, exist_ok=True)
print('\n')

# Evaluate model performance
pred = custom_cnn.predict(test_images)
pred = np.argmax(pred, axis=1)

# Map the label
labels = (train_images.class_indices)
labels = dict((v, k) for k, v in labels.items())
pred = [labels[k] for k in pred]
y_test = list(test_df.Label)

# Apply a consistent and appealing style
sns.set(style="whitegrid")

print(f"\n{'=' * 20} Model: Custom CNN Model {'=' * 20}")

test_images.reset()

# Predictions
y_pred = custom_cnn.predict(test_images)
y_pred_classes = np.argmax(y_pred, axis=1)

# True labels
y_true = test_images.classes

# Misclassification error
misclassification_error = 1 - accuracy_score(y_true, y_pred_classes)
print(f'Misclassification Error: {misclassification_error:.4f}')

# Get the class labels
class_labels = ['Fruit Damage', 'leaf blight', 'Rhizopus rot', 'Healthy leaf', 'Healthy jackfruit', 'Leaf spot']

# Confusion matrix
cm = confusion_matrix(y_true, y_pred_classes)
plt.figure(figsize=(10, 8), dpi=300)

# Use the "Blues" color map for the confusion matrix
sns.heatmap(cm, annot=True, fmt='g', cmap='Blues', xticklabels=class_labels, yticklabels=class_labels)
plt.title('Confusion Matrix')
plt.xlabel('Predicted')
plt.ylabel('True')

# Save the confusion matrix plot
cm_plot_path = os.path.join(output_dir, 'confusion_matrix_hybrid.png')
plt.savefig(cm_plot_path, bbox_inches='tight')
plt.show()

