"""## Step 7 PreLU"""

from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Conv2D, AveragePooling2D, Flatten, Dense, Dropout, BatchNormalization
from tensorflow.keras.optimizers import Adam
import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from tensorflow.keras.models import load_model
from sklearn import metrics
from sklearn.metrics import classification_report, confusion_matrix
from statistics import mean
from tensorflow.keras.layers import PReLU
def custom_cnn_model():
    model = Sequential()
    # First Convolutional Block
    model.add(Conv2D(32, (3, 3), kernel_initializer='he_uniform', padding='same', input_shape=(224, 224, 3)))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))

    # Second Convolutional Block
    model.add(Conv2D(64, (3, 3), kernel_initializer='he_uniform', padding='same'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.2))

    # Third Convolutional Block
    model.add(Conv2D(64, (3, 3), kernel_initializer='he_uniform', padding='same'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(Conv2D(64, (3, 3), kernel_initializer='he_uniform', padding='same'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.3))

    # Fourth Convolutional Block
    model.add(Conv2D(128, (3, 3), kernel_initializer='he_uniform', padding='same'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(Conv2D(128, (3, 3), kernel_initializer='he_uniform', padding='same'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.4))

    # Fully Connected Block
    model.add(Flatten())
    model.add(Dense(256, kernel_initializer='he_uniform'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(Dropout(0.5))
    model.add(Dense(128, kernel_initializer='he_uniform'))
    model.add(PReLU())  # Using PReLU
    model.add(BatchNormalization())
    model.add(Dropout(0.3))    # Output Layer
    model.add(Dense(6, activation='softmax'))

    # Compile the Model
    opt = Adam(learning_rate=0.001)
    model.compile(optimizer=opt, loss='categorical_crossentropy', metrics=['accuracy'])

    return model
# Fit the model
custom_cnn = custom_cnn_model()
history_cnn = custom_cnn.fit(train_images, validation_data=val_images,batch_size=32, epochs=20, verbose=1)
# Directory to save the figures
output_dir = '/content/drive/MyDrive/JackFruit/Ablation/CustomCNNModel/s7'
os.makedirs(output_dir, exist_ok=True)
print('\n')

# Evaluate model performance
