"""## Step 9 Tanh"""

from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Conv2D, AveragePooling2D, Flatten, Dense, Dropout, BatchNormalization
from tensorflow.keras.optimizers import Adam
import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from tensorflow.keras.models import load_model
from sklearn import metrics
from sklearn.metrics import classification_report, confusion_matrix
from statistics import mean
def custom_cnn_model():
    model = Sequential()
    # First Convolutional Block
    model.add(Conv2D(32, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same', input_shape=(224, 224, 3)))
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    # Second Convolutional Block
    model.add(Conv2D(64, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same'))
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.2))
    # Third Convolutional Block
    model.add(Conv2D(64, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same'))
    model.add(BatchNormalization())
    model.add(Conv2D(64, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same'))
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.3))
    # Fourth Convolutional Block
    model.add(Conv2D(128, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same'))
    model.add(BatchNormalization())
    model.add(Conv2D(128, (3, 3), activation='tanh', kernel_initializer='he_uniform', padding='same'))
    model.add(BatchNormalization())
    model.add(AveragePooling2D((2, 2)))
    model.add(Dropout(0.4))

    # Fully Connected Block
    model.add(Flatten())
    model.add(Dense(256, activation='relu', kernel_initializer='he_uniform'))
    model.add(BatchNormalization())
    model.add(Dropout(0.5))
    model.add(Dense(128, activation='relu', kernel_initializer='he_uniform'))
    model.add(BatchNormalization())
    model.add(Dropout(0.3))

    # Output Layer
    model.add(Dense(6, activation='softmax'))

    # Compile the Model
    opt = Adam(learning_rate=0.001)
    model.compile(optimizer=opt, loss='categorical_crossentropy', metrics=['accuracy'])

    return model
# Fit the model
