import os
import shutil
import numpy as np
import random
import matplotlib.pyplot as plt

y_test = list(test_df.Label)
pred = custom_cnn.predict(test_images)
pred_labels = np.argmax(pred, axis=1)

# Reverse class_indices to get label names
labels = (train_images.class_indices)
labels = dict((v, k) for k, v in labels.items())
pred_labels = [labels[k] for k in pred_labels]

# Create a directory to save misclassified images
misclassified_dir = "/content/drive/MyDrive/JackFruit/MisclassifiedImages"
os.makedirs(misclassified_dir, exist_ok=True)

# Identify misclassified images and save them
misclassified_indices = [i for i in range(len(y_test)) if y_test[i] != pred_labels[i]]

for idx in misclassified_indices:
    image_path = test_images.filepaths[idx]  # Get the original file path
    true_label = y_test[idx]
    pred_label = pred_labels[idx]

    # Create a subfolder for the true class if it doesn't exist
    class_folder = os.path.join(misclassified_dir, true_label)
    os.makedirs(class_folder, exist_ok=True)

    # Copy the misclassified image to the new folder
    image_name = os.path.basename(image_path)
    new_image_path = os.path.join(class_folder, f"{pred_label}_misclassified_{image_name}")
    shutil.copy(image_path, new_image_path)

print("Misclassified images saved successfully.")

# Show 6 random images, one from each class, with true and predicted labels
classes = os.listdir(misclassified_dir)
fig, axes = plt.subplots(1, 6, figsize=(20, 5))
fig.suptitle('Random Misclassified Images from Each Class', fontsize=16)
for i, ax in enumerate(axes):
    class_folder = os.path.join(misclassified_dir, classes[i])
    class_images = os.listdir(class_folder)
    random_image = random.choice(class_images)
    img_path = os.path.join(class_folder, random_image)

    # Load and display the image
    img = plt.imread(img_path)
    true_label = classes[i]
    pred_label = random_image.split('_')[0]  # Extract predicted label from the filename

    ax.imshow(img)
    ax.axis('off')
    ax.set_title(f"True: {true_label}\nPred: {pred_label}")

plt.show()

