import gradio as gr
import tensorflow as tf
import numpy as np
from PIL import Image

# Load your trained model
model = tf.keras.models.load_model('/content/drive/MyDrive/JackFruit/Fine Tuned/HyBridModel/hybrid_model.h5')

# Suppress the warning by recompiling the model with dummy metrics
model.compile(optimizer='adam', loss='categorical_crossentropy', metrics=['accuracy'])

# Read class names from fruit.txt
with open('/content/drive/MyDrive/JackFruit/fruit.txt', 'r') as f:
    class_names = [line.strip() for line in f.readlines()]

# Prediction function
def predict(image):
    # Preprocess the image to match the model input
    img = image.resize((224, 224))
    img = np.array(img) / 255.0  # Normalize the image
    img = np.expand_dims(img, axis=0)

    # Predict using the model
    predictions = model.predict(img)
    confidence = np.max(predictions)
    predicted_class = class_names[np.argmax(predictions)]

    return predicted_class, confidence, img

# Gradio interface
def gradio_interface(image):
    predicted_class, confidence, img = predict(image)
    confidence_percentage = int(confidence * 100)

    # Create a progress bar with confidence label
    progress_html = f"""
    <p style="font-size: 32px; text-align: center; color: #C9D4D4; margin-bottom: 5px;">Confidence: {confidence_percentage}%</p>
    <div style="width: 100%; background-color: #ddd; border-radius: 25px;">
        <div style="width: {confidence_percentage}%; height: 40px; background-color: #4caf50; border-radius: 25px; text-align: center; line-height: 40px; color: white; font-size: 24px;">
            {confidence_percentage}%
        </div>
    </div>
    """

    # Convert the preprocessed image back to PIL format for display
    display_image = Image.fromarray((img[0] * 255).astype(np.uint8))

    return display_image, gr.HTML(f"<p style='font-size: 36px; text-align: center; color: #F9AB00; font-weight: bold;'>{predicted_class}</p>"), gr.HTML(progress_html)

# Custom CSS to apply
css = """
body {
    background-color: #f7f7f7;
    font-family: 'Arial', sans-serif;
    color: #444;
}

h1, h2, h3, p {
    color: #f0f0f0; /* Off white color for title and text */
    font-size: 20px; /* Increase font size */
}

.gr-container {
    max-width: 800px;
    margin: auto;
    padding: 20px;
    background-color: white;
    border-radius: 15px;
    box-shadow: 0px 0px 15px rgba(0, 0, 0, 0.2);
}

.gr-button-primary {
    background-color: #4caf50;
    border-color: #4caf50;
    font-size: 22px;
    padding: 12px 24px;
    border-radius: 25px;
}

.gr-button-primary:hover {
    background-color: #45a049;
}

.gr-image {
    margin-bottom: 20px;
    border-radius: 15px;
    box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
    width: 224px;
    height: 224px;
    object-fit: cover;
}

#prediction-result {
    font-size: 36px;
    font-weight: bold;
    text-align: center;
    color: #4caf50;
    margin-bottom: 20px;
}

.progress-container {
    margin-top: 20px;
    margin-bottom: 20px;
}
"""

# Launch the Gradio app
iface = gr.Interface(
    fn=gradio_interface,
    inputs=gr.Image(type="pil", label="Upload Image", image_mode="RGB"),
    outputs=[gr.Image(type="pil", label="Processed Image"), gr.HTML(elem_id="prediction-result"), gr.HTML()],
    title="JackVisualNet - JackFruit Disease Classification",
    description="Upload an image of a Jackfruit to classify it's Disease. The model will display the prediction and the confidence score below the image.",
    css=css  # Apply CSS here
)

iface.launch(share=True)

