import os
import numpy as np
import matplotlib.pyplot as plt
from PIL import Image
import torch
import torchvision
from torchvision import transforms
from pytorch_grad_cam import GradCAM, GradCAMPlusPlus
from pytorch_grad_cam.utils.image import show_cam_on_image

# Load your pre-trained model (DenseNet201 used here)
model = torchvision.models.densenet201(pretrained=True)
model.eval()

# Select the target layer for Grad-CAM (usually the last conv layer)
target_layer = model.features[-1]  # The final convolutional layer in DenseNet201

# Transformation for the input image
transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
])

# Function to generate and save Grad-CAM visualizations
def process_image(image_path, label_text="Image", target_category=None):
    input_image = Image.open(image_path).convert("RGB")
    input_tensor = transform(input_image).unsqueeze(0)  # Add batch dimension

    # Check CUDA availability and move model if available
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model.to(device)
    input_tensor = input_tensor.to(device)

    # Use GradCAM and GradCAM++
    cam = GradCAM(model=model, target_layers=[target_layer])  # Remove use_cuda
    cam_plus_plus = GradCAMPlusPlus(model=model, target_layers=[target_layer]) # Remove use_cuda

    # Generate Grad-CAM and Grad-CAM++ visualizations
    grayscale_cam = cam(input_tensor=input_tensor)[0]  # No target category specified
    grayscale_cam_plus_plus = cam_plus_plus(input_tensor=input_tensor)[0]

    # Convert image back to numpy for overlay
    img = np.array(input_image.resize((224, 224))) / 255.0

    # Superimpose Grad-CAM on the original image
    visualization = show_cam_on_image(img, grayscale_cam, use_rgb=True)
    visualization_plus_plus = show_cam_on_image(img, grayscale_cam_plus_plus, use_rgb=True)

    # Save the results
    base_name = os.path.basename(image_path).split('.')[0]
    output_path_grad_cam = os.path.join(output_folder, f"{base_name}_grad_cam.png")
    output_path_grad_cam_plus_plus = os.path.join(output_folder, f"{base_name}_grad_cam_plus_plus.png")

    # Save images
    plt.imsave(output_path_grad_cam, visualization)
    plt.imsave(output_path_grad_cam_plus_plus, visualization_plus_plus)

    # Display original and Grad-CAM visualizations in the terminal
    plt.figure(figsize=(15, 5))

    # Display the original image with label in title
    plt.subplot(1, 3, 1)
    plt.imshow(img)
    plt.title(f'Original Image ({label_text})')

    # Display Grad-CAM visualization
    plt.subplot(1, 3, 2)
    plt.imshow(visualization)
    plt.title('Grad-CAM')

    # Display Grad-CAM++ visualization
    plt.subplot(1, 3, 3)
    plt.imshow(visualization_plus_plus)
    plt.title('Grad-CAM++')

    # Show the images
    plt.show()

# Define the folder and output path
input_folder = '/content/drive/MyDrive/JackFruit/Miss Hybrid'
output_folder = '/content/drive/MyDrive/JackFruit/GradCAM_Results_Hybrid'
os.makedirs(output_folder, exist_ok=True)

# Process all images in the input folder
image_files = [os.path.join(input_folder, f) for f in os.listdir(input_folder) if f.lower().endswith(('png', 'jpg', 'jpeg'))]

# Loop through and process each image
for image_path in image_files:
    process_image(image_path)

print(f"Grad-CAM and Grad-CAM++ visualizations have been saved in {output_folder}.")

"""## USing my hybrid Model"""

import os
import numpy as np
import matplotlib.pyplot as plt
from PIL import Image
import tensorflow as tf
from tensorflow import keras
from tf_keras_vis.gradcam import Gradcam, GradcamPlusPlus
from tf_keras_vis.utils.model_modifiers import ReplaceToLinear
from tf_keras_vis.utils.scores import CategoricalScore
import cv2

# Directory containing the images
image_folder = '/content/drive/MyDrive/JackFruit/Miss Hybrid'
output_folder = '/content/drive/MyDrive/JackFruit/GradCAM_Results_Hybrid'  # Folder to save Grad-CAM results

# Create the output directory if it doesn't exist
os.makedirs(output_folder, exist_ok=True)

# Preprocessing: Image transformations (resize, normalize)
def preprocess_image(img_path):
    img = Image.open(img_path).convert('RGB').resize((224, 224))
    img = np.array(img) / 255.0  # Normalize to [0, 1]
    img = (img - [0.485, 0.456, 0.406]) / [0.229, 0.224, 0.225]  # Apply mean and std normalization
    return np.expand_dims(img, axis=0)  # Add batch dimension

# Load your Keras model
model_path = '/content/drive/MyDrive/JackFruit/Fine Tuned/HyBridModel/hybrid_model.h5'
model = keras.models.load_model(model_path)

# Define Grad-CAM and Grad-CAM++ objects
gradcam = Gradcam(model, model_modifier=ReplaceToLinear(), clone=True)
gradcam_plus_plus = GradcamPlusPlus(model, model_modifier=ReplaceToLinear(), clone=True)

# Function to apply colormap and overlay on the original image
def apply_colormap_on_image(org_img, activation, colormap_name='jet'):
    # Normalize the activation map to 0-255
    heatmap = np.uint8(255 * activation)
    # Apply the colormap
    colormap = cv2.applyColorMap(heatmap, cv2.COLORMAP_JET)
    colormap = cv2.cvtColor(colormap, cv2.COLOR_BGR2RGB)  # Convert BGR to RGB

    # Overlay the heatmap on the original image
    overlayed_image = 0.5 * org_img + 0.5 * colormap / 255.0
    overlayed_image = np.clip(overlayed_image, 0, 1)  # Clip values to ensure valid range
    return overlayed_image

# Function to process each image and generate Grad-CAM visualizations
def process_images_with_gradcam(folder):
    images = [os.path.join(folder, f) for f in os.listdir(folder) if f.lower().endswith(('png', 'jpg', 'jpeg'))]

    for image_path in images:
        img = preprocess_image(image_path)

        # Get the class index with the highest score as the target
        predictions = model.predict(img)
        class_index = np.argmax(predictions[0])

        # Define the score function
        score = CategoricalScore(class_index)

        # Generate Grad-CAM and Grad-CAM++ heatmaps
        cam = gradcam(score, img, penultimate_layer=-1)
        cam_plus_plus = gradcam_plus_plus(score, img, penultimate_layer=-1)

        # Original image for overlay
        original_img = np.squeeze(img)  # Remove batch dimension
        original_img = (original_img * [0.229, 0.224, 0.225]) + [0.485, 0.456, 0.406]  # De-normalize
        original_img = np.clip(original_img, 0, 1)  # Clip values to [0, 1]

        # Apply colormap and create overlays
        overlay_cam = apply_colormap_on_image(original_img, cam[0])
        overlay_cam_plus_plus = apply_colormap_on_image(original_img, cam_plus_plus[0])

        # Plot original image and Grad-CAM visualizations side by side
        plt.figure(figsize=(15, 5))

        # Original image
        plt.subplot(1, 3, 1)
        plt.imshow(original_img)
        plt.title('Original Image')
        plt.axis('off')  # Remove axes for a cleaner image

        # Grad-CAM
        plt.subplot(1, 3, 2)
        plt.imshow(overlay_cam)
        plt.title('Grad-CAM')
        plt.axis('off')  # Remove axes for a cleaner image

        # Grad-CAM++
        plt.subplot(1, 3, 3)
        plt.imshow(overlay_cam_plus_plus)
        plt.title('Grad-CAM++')
        plt.axis('off')  # Remove axes for a cleaner image

        # Show the images side by side
        plt.show()

        # Save the visualizations
        base_name = os.path.basename(image_path).split('.')[0]
        output_path_cam = os.path.join(output_folder, f"{base_name}_grad_cam.png")
        output_path_cam_plus_plus = os.path.join(output_folder, f"{base_name}_grad_cam_plus_plus.png")

        plt.imsave(output_path_cam, overlay_cam)
        plt.imsave(output_path_cam_plus_plus, overlay_cam_plus_plus)
        print(f"Grad-CAM and Grad-CAM++ visualizations saved at {output_folder}")

# Process all images in the folder
process_images_with_gradcam(image_folder)

print(f"Grad-CAM and Grad-CAM++ visualizations for all images have been saved in {output_folder}.")

