output_folder = '/content/drive/MyDrive/JackFruit/LIME_Results_pretrained_classified'  # Folder to save LIME results

# Create the output directory if it doesn't exist
os.makedirs(output_folder, exist_ok=True)

# Preprocessing: Image transformations (resize, normalize)
transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225])
])

model = models.densenet201(pretrained=True)
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu') # Get the device
model.to(device) # Move the model to the device
model.eval()

# Prediction function for LIME
def predict_fn(images):
    # Convert list of images to tensor batch
    batch = torch.stack([transform(Image.fromarray(img).convert('RGB')) for img in images], dim=0)
    # Ensure the batch is on the correct device (CPU or GPU)
    batch = batch.to(torch.device('cuda' if torch.cuda.is_available() else 'cpu'))

    # Send batch to model and get predictions
    with torch.no_grad():
        output = model(batch)
    # Return the predictions as probabilities using softmax
    probabilities = torch.nn.functional.softmax(output, dim=1).cpu().numpy()
    return probabilities

# LIME explainer
explainer = lime_image.LimeImageExplainer()

# Function to process each image in the folder
def process_images_in_folder(folder):
    images = [os.path.join(folder, f) for f in os.listdir(folder) if f.lower().endswith(('png', 'jpg', 'jpeg'))]

    for image_path in images:
        img = np.array(Image.open(image_path).convert('RGB'))  # Ensure the image is RGB

        # Check if the image has valid dimensions
        if img.shape[-1] != 3:
            print(f"Skipping image {image_path} due to invalid shape.")
            continue

        # LIME explanation
        explanation = explainer.explain_instance(
            img, predict_fn, top_labels=1, hide_color=0, num_samples=1000
        )

        # Get image segmentation and boundaries
        temp, mask = explanation.get_image_and_mask(
            explanation.top_labels[0],
            positive_only=False,
            hide_rest=True,
            num_features=5,
            min_weight=0.01
        )

        # Use mark_boundaries to draw boundary lines
        boundary_image = mark_boundaries(img / 255.0, mask, color=(1, 1, 0), mode='thick')  # Use yellow for lines

        # Plot original image and LIME explanation side by side
        plt.figure(figsize=(10, 5))

        # Original image
        plt.subplot(1, 2, 1)
        plt.imshow(img)
        plt.title('Original Image')
        plt.axis('off')  # Remove axes for a cleaner image

        # LIME explanation with boundary lines
        plt.subplot(1, 2, 2)
        plt.imshow(boundary_image)
        plt.title('LIME Explanation')
        plt.axis('off')  # Remove axes for a cleaner image

        # Show the images side by side
        plt.show()

        # Save the boundary image
        output_path = os.path.join(output_folder, f"{os.path.basename(image_path).split('.')[0]}_lime.png")
        plt.imsave(output_path, boundary_image)
