"""## MISS"""

import os
import numpy as np
import matplotlib.pyplot as plt
from PIL import Image
import tensorflow as tf
from tensorflow import keras
from tf_keras_vis.saliency import Saliency
from tf_keras_vis.utils.model_modifiers import ReplaceToLinear
from tf_keras_vis.utils.scores import CategoricalScore
from tf_keras_vis.scorecam import ScoreCAM
# from tf_keras_vis.faster_scorecam import FasterScoreCAM
import cv2

# Directory containing the images
image_folder = '/content/drive/MyDrive/JackFruit/Miss Hybrid'
output_folder = '/content/drive/MyDrive/JackFruit/XAI_Results_Hybrid'  # Folder to save XAI results

# Create the output directory if it doesn't exist
os.makedirs(output_folder, exist_ok=True)

# Preprocessing: Image transformations (resize, normalize)
def preprocess_image(img_path):
    img = Image.open(img_path).convert('RGB').resize((224, 224))
    img = np.array(img) / 255.0  # Normalize to [0, 1]
    img = (img - [0.485, 0.456, 0.406]) / [0.229, 0.224, 0.225]  # Apply mean and std normalization
    return np.expand_dims(img, axis=0)  # Add batch dimension

# Load your Keras model
model_path = '/content/drive/MyDrive/JackFruit/Fine Tuned/HyBridModel/hybrid_model.h5'
model = keras.models.load_model(model_path)

# Define Score-CAM and Faster Score-CAM objects
score_cam = ScoreCAM(model, model_modifier=ReplaceToLinear(), clone=True)
# faster_score_cam = FasterScoreCAM(model, model_modifier=ReplaceToLinear(), clone=True)

# Define Vanilla Saliency and Smooth Grad
saliency = Saliency(model, model_modifier=ReplaceToLinear(), clone=True)

# Function to apply colormap and overlay on the original image
def apply_colormap_on_image(org_img, activation, colormap_name='jet'):
    heatmap = np.uint8(255 * activation)  # Normalize activation to 0-255
    colormap = cv2.applyColorMap(heatmap, cv2.COLORMAP_JET)
    colormap = cv2.cvtColor(colormap, cv2.COLOR_BGR2RGB)  # Convert BGR to RGB

    # Overlay the heatmap on the original image
    overlayed_image = 0.5 * org_img + 0.5 * colormap / 255.0
    overlayed_image = np.clip(overlayed_image, 0, 1)  # Clip values to ensure valid range
    return overlayed_image

# Function to process each image and generate visualizations
def process_images(folder):
    images = [os.path.join(folder, f) for f in os.listdir(folder) if f.lower().endswith(('png', 'jpg', 'jpeg'))]

    for image_path in images:
        img = preprocess_image(image_path)

        # Get the class index with the highest score as the target
        predictions = model.predict(img)
        class_index = np.argmax(predictions[0])

        # Define the score function
        score = CategoricalScore(class_index)

        # Generate Score-CAM and Faster Score-CAM heatmaps
        cam_score = score_cam(score, img, penultimate_layer=-1)
        # cam_faster_score = faster_score_cam(score, img, penultimate_layer=-1)

        # Generate Vanilla Saliency and Smooth Grad
        vanilla_saliency = saliency(score, img)
        smooth_grad = saliency(score, img, smooth_samples=20, smooth_noise=0.20)

        # Original image for overlay
        original_img = np.squeeze(img)  # Remove batch dimension
        original_img = (original_img * [0.229, 0.224, 0.225]) + [0.485, 0.456, 0.406]  # De-normalize
        original_img = np.clip(original_img, 0, 1)  # Clip values to [0, 1]

        # Apply colormap and create overlays
        overlay_score_cam = apply_colormap_on_image(original_img, cam_score[0])
        # overlay_faster_score_cam = apply_colormap_on_image(original_img, cam_faster_score[0])
        overlay_vanilla_saliency = apply_colormap_on_image(original_img, vanilla_saliency[0])
        overlay_smooth_grad = apply_colormap_on_image(original_img, smooth_grad[0])

        # Plot original image and visualizations
        plt.figure(figsize=(20, 5))

        # Original image
        plt.subplot(1, 5, 1)
        plt.imshow(original_img)
        plt.title('Original Image')
        plt.axis('off')

        # Score-CAM
        plt.subplot(1, 5, 2)
        plt.imshow(overlay_score_cam)
        plt.title('Score-CAM')
        plt.axis('off')

        # # Faster Score-CAM
        # plt.subplot(1, 5, 3)
        # plt.imshow(overlay_faster_score_cam)
        # plt.title('Faster Score-CAM')
        # plt.axis('off')

        # Vanilla Saliency
        plt.subplot(1, 5, 4)
        plt.imshow(overlay_vanilla_saliency)
        plt.title('Vanilla Saliency')
        plt.axis('off')

        # Smooth Grad
        plt.subplot(1, 5, 5)
        plt.imshow(overlay_smooth_grad)
        plt.title('Smooth Grad')
        plt.axis('off')

        # Show the images
        plt.show()

        # Save the visualizations
        base_name = os.path.basename(image_path).split('.')[0]
        output_path_score_cam = os.path.join(output_folder, f"{base_name}_score_cam.png")
        # output_path_faster_score_cam = os.path.join(output_folder, f"{base_name}_faster_score_cam.png")
        output_path_vanilla_saliency = os.path.join(output_folder, f"{base_name}_vanilla_saliency.png")
        output_path_smooth_grad = os.path.join(output_folder, f"{base_name}_smooth_grad.png")

        plt.imsave(output_path_score_cam, overlay_score_cam)
        # plt.imsave(output_path_faster_score_cam, overlay_faster_score_cam)
        plt.imsave(output_path_vanilla_saliency, overlay_vanilla_saliency)
        plt.imsave(output_path_smooth_grad, overlay_smooth_grad)
        print(f"Visualizations saved for {base_name} at {output_folder}")

# Process all images in the folder
process_images(image_folder)

print(f"Visualizations for all images have been saved in {output_folder}.")

