"""## MissClassified"""

import os
import numpy as np
import matplotlib.pyplot as plt
from PIL import Image
import tensorflow as tf
from tensorflow import keras
import shap

# Load your Keras model
model_path = '/content/drive/MyDrive/JackFruit/Fine Tuned/HyBridModel/hybrid_model.h5'
model = keras.models.load_model(model_path)

# Preprocess image input for your model
def preprocess_image(img_path):
    """
    Preprocess the image for model prediction.
    - Resize to (224, 224)
    - Normalize to [0, 1]
    - Standardize using ImageNet mean and std values
    """
    img = Image.open(img_path).convert('RGB').resize((224, 224))  # Resize as per model's input size
    img = np.array(img) / 255.0  # Normalize pixel values to [0, 1]
    img = (img - [0.485, 0.456, 0.406]) / [0.229, 0.224, 0.225]  # Adjust for ImageNet preprocessing
    return np.expand_dims(img, axis=0)  # Add batch dimension

# Define the model prediction function for SHAP
def f(X):
    """
    SHAP-compatible function for model predictions.
    Ensures the input is preprocessed and passed through the model.

    Parameters:
        X (numpy.ndarray): A batch of images in numpy array format.

    Returns:
        numpy.ndarray: Model predictions for the input batch.
    """
    return model(X)


# Define your six-class names
class_names = ['Fruit damage', 'Healthy jackfruit','Healthy leaf',  'Leaf spot', 'Rhizopus rot','leaf blight']

# Create the masker for SHAP explanations
masker = shap.maskers.Image("inpaint_telea", (224, 224, 3))  # Masker compatible with SHAP image explainer

# Define the SHAP Explainer
explainer = shap.Explainer(f, masker, output_names=class_names)

# Function to process and explain multiple images
def process_images_with_shap(image_folder, output_folder):
    """
    Process images from a folder, explain predictions using SHAP,
    and save visualizations to the output folder.
    """
    # Ensure the output folder exists
    os.makedirs(output_folder, exist_ok=True)

    # List all image files in the folder
    images = [os.path.join(image_folder, f) for f in os.listdir(image_folder) if f.lower().endswith(('png', 'jpg', 'jpeg'))]

    for image_path in images:
        # Preprocess the image
        img = preprocess_image(image_path)

        # Get model predictions
        predictions = model.predict(img)

        # Debugging: Check predictions and output shape
        print(f"Predictions: {predictions}")
        print(f"Prediction shape: {predictions.shape}")

        # Handle models with a single output (e.g., binary classification or regression)
        if predictions.shape[-1] == 1:
            print("Warning: Model output indicates a single output class.")
            class_index = 0  # For single-output models, use the first index
        else:
            class_index = np.argmax(predictions[0])  # Class with the highest prediction score

        # Debugging: Ensure the class_index is valid
        print(f"Predicted class index: {class_index}")
        if class_index >= len(class_names):
            raise ValueError(f"Class index {class_index} is out of bounds for class names {class_names}")

        # Explain the prediction using SHAP
        shap_values = explainer(img)

        # Handle single-output models for SHAP visualization
        if predictions.shape[-1] == 1:
            shap.image_plot([shap_values[0]], [img])  # Use first SHAP value for regression/single-class outputs
        else:
            shap.image_plot([shap_values[class_index]], [img])  # Use predicted class SHAP value

        # Save the SHAP plot
        base_name = os.path.basename(image_path).split('.')[0]
        output_path = os.path.join(output_folder, f"{base_name}_shap.png")
        plt.savefig(output_path, bbox_inches='tight')
        plt.show()  # Close the plot to avoid overlapping issues
        print(f"Saved SHAP visualization for {base_name} at {output_path}")

# Set the paths for input images and output folder
image_folder = '/content/drive/MyDrive/JackFruit/Miss Hybrid'  # Folder containing images to process
output_folder = '/content/drive/MyDrive/JackFruit/SHAP_MISS'  # Folder to save SHAP visualizations

# Process all images and generate SHAP visualizations
process_images_with_shap(image_folder, output_folder)

print(f"SHAP visualizations have been successfully saved in {output_folder}.")

